    string = r'"(?:[^"\\]|\\.)*"'
    match = re.fullmatch(rf"([A-Za-z_][A-Za-z0-9_.]*)\(\s*((?:{string}\s*(?:,\s*{string}\s*)*)?)\)", source)
    if match is None:
